import React, { useEffect, useState, useRef } from "react";
import axios from "axios";
import {
  MapContainer,
  TileLayer,
  Polyline,
  Marker,
  Tooltip
} from "react-leaflet";
import "leaflet/dist/leaflet.css";
import L from "leaflet";

import {
  Line
} from "react-chartjs-2";

import {
  Chart as ChartJS,
  LineElement,
  CategoryScale,
  LinearScale,
  PointElement,
  Legend
} from "chart.js";

ChartJS.register(LineElement, CategoryScale, LinearScale, PointElement, Legend);

function App() {
  const [data, setData] = useState([]);
  const [path, setPath] = useState([]);
  const [index, setIndex] = useState(0);
  const [playing, setPlaying] = useState(false);

  const [startTime, setStartTime] = useState("");
  const [endTime, setEndTime] = useState("");

  const mapRef = useRef();

  // 📊 POINTS PER SECOND
 function computePointsPerSecond(data) {
  const bucket = {};

  data.forEach(p => {
    const ts = new Date(p.timestamp);

    // 🔥 ROUND TO SECOND (KEY FIX)
    const key = Math.floor(ts.getTime() / 1000);

    if (!bucket[key]) bucket[key] = 0;
    bucket[key]++;
  });

  const labels = Object.keys(bucket);
  const values = Object.values(bucket);

  return { labels, values };
}

  // 🚀 FETCH
  const fetchData = async () => {
    try {
      const res = await axios.get("http://localhost:3000/path", {
        params: {
          start: startTime,
          end: endTime
        }
      });

      const d = res.data;

      if (!d.length) {
        alert("No data found");
        return;
      }

      setData(d);
      setIndex(0);

      const coords = d.map(p => ({
        lat: p.location.coordinates[1],
        lng: p.location.coordinates[0],
        alt: p.alt || 0,
        voltage: p.voltage || 0
      }));

      setPath(coords);

      if (coords.length && mapRef.current) {
        const bounds = coords.map(c => [c.lat, c.lng]);
        mapRef.current.fitBounds(bounds);
      }

    } catch (err) {
      console.error(err);
    }
  };

  // ▶ PLAY
  useEffect(() => {
    if (!playing) return;

    const interval = setInterval(() => {
      setIndex(prev => {
        if (prev >= path.length - 1) return prev;
        return prev + 1;
      });
    }, 100);

    return () => clearInterval(interval);
  }, [playing, path]);

  // 📍 FOLLOW
  useEffect(() => {
    if (path[index] && mapRef.current) {
      mapRef.current.flyTo(
        [path[index].lat, path[index].lng],
        18
      );
    }
  }, [index]);

  // 📊 CHARTS
  const chartData = {
    labels: path.slice(0, index).map((_, i) => i),
    datasets: [
      {
        label: "Altitude",
        data: path.slice(0, index).map(p => p.alt),
        borderColor: "cyan"
      },
      {
        label: "Battery",
        data: path.slice(0, index).map(p => p.voltage),
        borderColor: "yellow"
      }
    ]
  };

  const pps = computePointsPerSecond(
  data.slice(0, index)
);

  const ppsChart = {
    labels: pps.labels,
    datasets: [
      {
        label: "Points/sec",
        data: pps.values,
        borderColor: "lime"
      }
    ]
  };

  const chartOptions = {
    plugins: {
      legend: {
        labels: { color: "white" }
      }
    },
    scales: {
      x: { ticks: { color: "white" } },
      y: { ticks: { color: "white" } }
    }
  };

  return (
    <div style={{ background: "black", color: "white", height: "100vh" }}>
      <h2>🚁 Drone Playback</h2>

      {/* ⏱ FILTER */}
      <div>
        <input type="datetime-local" onChange={e => setStartTime(e.target.value)} />
        <input type="datetime-local" onChange={e => setEndTime(e.target.value)} />
        <button onClick={fetchData}>Apply</button>
      </div>

      {/* ▶ CONTROLS */}
      <div>
        <button onClick={() => setPlaying(true)}>▶ Play</button>
        <button onClick={() => setPlaying(false)}>⏸ Pause</button>
      </div>

      {/* 🗺 MAP */}
      <MapContainer
        center={[12.97, 77.59]}
        zoom={13}
        style={{ height: "60vh" }}
        whenCreated={map => (mapRef.current = map)}
      >
        <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

        <Polyline
          positions={path.slice(0, index).map(p => [p.lat, p.lng])}
          color="cyan"
        />

        {/* 🔵 DOT */}
        {path[index] && (
          <Marker
            position={[path[index].lat, path[index].lng]}
            icon={L.divIcon({
              html: `<div style="
                width:14px;height:14px;
                background:cyan;
                border-radius:50%;
                border:2px solid white;"></div>`
            })}
          >
            <Tooltip>
              Alt: {path[index].alt} <br />
              Battery: {path[index].voltage}
            </Tooltip>
          </Marker>
        )}
      </MapContainer>

      {/* 📊 ALT + BATTERY */}
      <div style={{ height: "20vh", background: "#111" }}>
        <Line data={chartData} options={chartOptions} />
      </div>

      {/* 📊 PPS */}
      <div style={{ height: "20vh", background: "#111" }}>
        <Line data={ppsChart} options={chartOptions} />
      </div>
    </div>
  );
}

export default App;
